INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7e55b3c1-489b-47c8-b2d2-801836ada53b', '21feff02-016d-46e2-bb9d-c27495133b1b', '70. óra: Feladatok megoldása', 'Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "18d7552c-e1e0-455d-8832-8f22f068fefa", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "b757841c-5c04-472a-af17-d0a3d4b0dd67", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "badd0232-c410-4127-91a5-ac02241e29ac", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "6de69662-12ca-455d-ab5a-14b4782a40f7", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "f1723252-aae9-43b7-840d-c6d0b9a6cd4f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6b4774ac-d91f-4c26-9d84-6d5a4826da19", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "0dc3798b-8fe7-4d38-9ff2-df12227eb864", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "b2642691-bde2-49da-b0a3-a6b992e20ec4", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "b554db38-028d-4b94-a7de-c59fd1a50b16", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "84a974b5-d16f-4623-9121-9f85be912977", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "692d9661-6db9-42a8-9aae-44ecd7c2c379", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "3df82bfc-25c2-437a-b6c0-c55778af718f", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "3bd04884-dc2d-4083-93f8-f9d76d20f608", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "2d533cb3-ee24-4acf-98de-8d832205f801", "text": "Igaz", "isCorrect": true}, {"id": "1aed6f04-01fa-4d48-89ed-aecceff2f3bf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('00eca8c9-ad8d-42c6-bc0b-aee899b1ff93', '21feff02-016d-46e2-bb9d-c27495133b1b', '71. óra: Egyenes arányosság', 'Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "79e5fc77-1263-4bc3-b001-f3a61d93dc4b", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "126a63ed-04ba-469e-ba52-215b184174d8", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "cac6687a-1d18-4904-bfea-4cc6a93f613b", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "0a85637f-97e4-44c3-86f0-79eb5955c96b", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "7c8a8269-2a29-4950-8847-874291868c00", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "9aa70e2c-f34b-4a7f-bdda-40bce23570f9", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "3c14b0c6-a796-4d83-9cdc-4a5c85649c2b", "text": "Igaz", "isCorrect": true}, {"id": "de124a05-472b-46c3-8613-10263c986a3f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "beb19d1f-a095-4578-8345-ca919eae66b1", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "20718aa5-eefd-4ef1-a34b-ed9b5edb7085", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "293659d8-9088-409e-a5f5-e2f5c6889ad8", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "a7ce0252-9b57-4d17-badf-32a5f93198d2", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "9d852d09-3d26-4131-9eea-f373bcf6bb81", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "5c35ee5d-0479-4e5e-a015-0e86e1f1b1d8", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "a8ab3f17-4e75-49e6-a35c-3de9ec46aa30", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "8bc4b2db-4520-43b8-9cde-4a63a0d364ef", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "d1a5cc0a-b95e-4271-bb25-c08a6013c581", "text": "Igaz", "isCorrect": true}, {"id": "a79dd511-4149-4062-a2a5-6db1d76fe442", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ad30d53a-ac51-4a22-b45c-383dd2cf8210", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7f6165f3-9db8-4449-aea3-59586274076f', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "beef3127-4235-446e-b410-de6b8a8a56ad", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "aae33ea2-198d-4e9f-85cb-a3925166616a", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "5f41fc42-6600-48ff-a218-293ed67a58fc", "text": "Parabola", "isCorrect": false}, {"id": "6d14cbe6-3c59-4568-9c08-6e5bd7bb12af", "text": "Körvonal", "isCorrect": false}, {"id": "c7654357-b4e6-463e-b155-450296bd83db", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "aa1bb9e5-e4b4-48c9-bedb-f34e51d7bebd", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "a800798c-ff98-4047-8d2d-ece94a7b08bb", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "d0d1ab05-212b-4b64-86a7-60ca5d0d3c57", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e313fbe8-91e8-4541-a540-2ecb10bf1913", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "e29fa312-4ecc-4f7c-81a9-03e5008d7b0c", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "b7d182ab-7e17-4d12-bed2-c6125f778a71", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "b131f2a5-50d4-46ff-a562-b6dc36f82034", "text": "Igaz", "isCorrect": true}, {"id": "30678c82-73a9-4aa1-9cb4-6abb89a43552", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "326cbba6-cbbb-4bbf-8b5d-7bd22b30dd64", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "7452ce80-b9f2-4454-94ec-37719eb67a94", "text": "Igaz", "isCorrect": true}, {"id": "250e2e9e-1199-4c85-b502-49440716be21", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f37b0c9e-4566-4b43-b32f-14612b2dd00d", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "f88f57cb-f245-43eb-b908-4c6d2200ca11", "text": "Igaz", "isCorrect": true}, {"id": "bb9f5ad9-d13a-4d9e-9525-d1710c5661fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('286f5fc8-9b5c-4068-b739-5f390809c49f', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d8157b52-602a-4158-82a6-0c14b41c7304", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "1e0eeec0-7859-4a9f-b66c-94b277125a55", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "60eded45-827f-4d14-be18-7be042ca969e", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "3662549e-0564-4eaa-ab82-df859b5ba768", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "157fc0f8-0aa0-4f9d-bca6-ab7a6bd295b2", "text": "Igaz", "isCorrect": true}, {"id": "a5124d6b-42ed-4671-bc8c-c05a10483548", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5d45f0b8-56dc-4409-bce5-e0b2f4fa0eae", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "5302ae71-b26d-4d22-b6b2-fe6acb8b3425", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "3ba73c08-422b-49ce-9a20-af2566bc1a49", "text": "Igaz", "isCorrect": true}, {"id": "052dec29-f0f4-46cf-94d9-aeb963f2a1ba", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2e1ea926-657d-4aec-87da-95ca30397c3c", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('78627e50-dec0-41fd-b94a-51795eb2adaa', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "862a9aa2-ed8e-46ce-a453-5de6fceae24c", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "51efece4-4bc9-4d44-ae4a-c190d19feda3", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "d9b035ad-8ddb-40ea-9c0c-8925e43dd35e", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "997aabad-770b-4e31-a127-6ad8b2ce254d", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "35a79c6e-cf76-41e7-939d-e35ed73d7188", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "2b14eeea-50f1-40fb-ab95-94c54bcb5cae", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "f9d39046-c5a4-4d03-8b76-83650e29ed3e", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "026afc1f-a601-40e3-b756-d653a54bc89c", "text": "Igaz", "isCorrect": true}, {"id": "97e96242-9bcd-4a8b-963d-61a43d89506b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "edeab442-7950-4198-a256-d24c0cbe61b6", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "67d3caca-7eae-43a1-8c6a-573675cbe78a", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "333d9c35-ceaf-4eae-89aa-1fafa54ce4e8", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "e51fe28b-a3ed-411b-9bf7-88f2f83c1db5", "text": "Igaz", "isCorrect": true}, {"id": "2f838286-f721-4c05-ba79-183784f0629d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dbb2372c-4b1f-44aa-a237-e1fd3a57e22f", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "3b449c4b-aa74-4280-8b0d-17681b7b6014", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "70429e42-7450-41d1-9ec7-4f676e3dbf95", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "45ddbabb-c28a-412c-b0fd-1b6c15ea1e9e", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "49ee8416-9e15-4b41-8b95-8cb1561feab2", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('024cc204-f003-4fa7-bd79-5a4987304806', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "2b70ed28-899f-48b0-af0a-c90d482df345", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "b09d3808-b4bd-4012-b693-dbd655b401fe", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "4561fb3c-4276-437c-8792-dcb990298989", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "c2168a36-1bc2-44b8-80e6-b55d666809fd", "text": "Igaz", "isCorrect": true}, {"id": "ce1ee3a6-83e7-4c5a-8ba1-f5ff428f75f9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8f1b797-2412-4ccd-be08-e7620411b710", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "486c791d-0841-470e-a0d9-4dbe3991d203", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "437e3d80-cb78-454d-a90d-9edb06a709c6", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "a3dcf3f3-3016-4dc9-a371-fbcb4e70ec77", "text": "5, 25, 125", "isCorrect": false}, {"id": "1526fbac-9a3f-4a39-9e61-224171e9b1b1", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "e748053f-3bad-41ac-914a-b8ac61d9f8be", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "3b19fd36-9610-432c-8faf-e4ed7ce25d87", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "51292617-f9ff-436d-b8de-b2655809ca22", "text": "Igaz", "isCorrect": true}, {"id": "79b7603f-4cbf-4a43-ac37-ef0e0772c7fb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8f2ac905-1610-4e0a-bc75-05f5301eff8b", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('de17e339-9003-42fc-ab27-9f65936fbf9e', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "663c5a88-a87f-4b67-87cf-26ab68ac1442", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "563d4af0-163b-4c78-9340-6834b41198a4", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "c11a3318-c043-42c4-be65-ea3cbbd09c99", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "abd5d1a9-2832-459c-a0fc-2b945145bc3b", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "af06282d-9aec-4032-a5c4-f873d91e7bab", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "f919dfef-8b8b-4444-a14d-e0d6aeb7c1da", "text": "Igaz", "isCorrect": true}, {"id": "659c0cbb-7b09-4bbb-b6b1-7e9c11f58ec3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "64479e54-81a3-4063-ace4-df8082af2fd4", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "e70a8bc7-df0a-438c-89cc-2aca208d9520", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "b40c4332-9b5e-40c0-a248-ed2484f2359b", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "9fcbda13-c5e3-4ca7-9df1-6acb6e590a17", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "be3fa484-f548-4492-9936-efbbfc253639", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "b3ff21d5-9f30-49c7-ae1c-5b32cdc1dc27", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "c867e660-d952-4d81-9f78-b5d96e3c6c15", "text": "Igaz", "isCorrect": true}, {"id": "429d7866-1805-42fc-b2e8-157ee317ebe4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('dd140e2d-cf82-4e29-b3dc-b5d1ea5cac68', '21feff02-016d-46e2-bb9d-c27495133b1b', '77. óra: Törtrész', 'Törtrész kiszámítása és kapcsolata az egyenes arányossággal.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "893528a6-b635-482c-a205-09c121a9dfbf", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "a00f64c7-e70d-46af-b824-4279f779d12a", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "1dcbf76d-aa29-4467-9360-a512bc78f879", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "a4b20c50-659a-4f3a-940f-942bbe93e5da", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "c22c95f6-44d0-4edd-821c-ea169dfc375d", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "506bbf8a-01d7-484c-85a9-6cdecb01626e", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b9611f78-9280-49c0-9181-15bb6b638f4c", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "99782c30-fe20-479f-bc56-ff94be522995", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "00990796-e966-4fbd-8a5b-74e0b658d7c7", "text": "Igaz", "isCorrect": true}, {"id": "26ad585d-3d17-42cd-ae8d-4006493f953e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f03c869-51c8-4a96-810b-972221687ea1", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "8773b9b4-23b6-474a-aa30-c122131d2ab9", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "7595edbc-cee7-416d-a9cf-d8a8feb8a73e", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a0ff6da7-d927-467e-b419-aa3717443c06', '21feff02-016d-46e2-bb9d-c27495133b1b', '78. óra: Feladatmegoldás', 'Összetett feladatok megoldása törtrész kiszámításával.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "5120134d-620b-4c88-bcc0-c53cb1281500", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "c7b043f7-5022-440a-b40e-0726b466f203", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "37d754d0-48eb-4667-ac7a-d80d64718a42", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "b470f909-a71c-4a1b-ae03-99a31a80ae6a", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "dca46efd-e395-426b-bcaf-0f58304ed8e3", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "f053cd42-1e35-44a6-8431-e458e28c0a07", "text": "Igaz", "isCorrect": true}, {"id": "b0ec0a8e-2c1d-4ff8-8b07-377a25346205", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4a67ff5b-f9cb-4652-8b4f-37607b65f036", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "c2b91f58-67f3-4e96-a523-a26df889a5f3", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "28a49fca-8a8a-4fb9-9792-2726b6b55107", "text": "Igaz", "isCorrect": true}, {"id": "332ecaa0-6cbb-4fd9-9b9c-7cd3e84dc8f1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('79e2f6b3-7da0-40fe-96e5-3a4e2e07c9dd', '21feff02-016d-46e2-bb9d-c27495133b1b', '79. óra: Számonkérés', 'Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "953b920e-cc7f-4d84-9e75-99b2df441298", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "9151c628-388a-4c5f-be3b-d5f78bc74471", "text": "1 : 3", "isCorrect": true}, {"id": "f8420baa-dcdd-44e2-bfa5-7975384016c4", "text": "1 : 2", "isCorrect": false}, {"id": "fd19add2-e55f-466b-8b11-3cae99a90a36", "text": "3 : 1", "isCorrect": false}, {"id": "e8fecbe7-74bb-43e0-9c4a-218b0c78fe23", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "450443bb-e122-4005-9731-70fb6a091d67", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "75df480b-7c33-4973-8fe1-865bc60281f5", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "7caf6764-d7a4-4acd-b141-5a597a0297b9", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "804c3c02-0d1a-43ba-bb09-fda472282683", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "80d30943-d625-4815-88a5-a52f5719f3ff", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "b053ddca-142f-4154-aba9-50172969e430", "text": "Igaz", "isCorrect": true}, {"id": "8d02077f-0392-4984-b215-65a08c9ac073", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20d4f697-07e9-4e53-836f-7a8654288e14", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "ce4ff5c8-9d0b-4a6b-b437-4f7739b30838", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "25571b9a-f158-4b1e-8910-241e73d56bdb", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "e70e27fd-9cdf-4c56-a931-420df3da5371", "text": "Igaz", "isCorrect": true}, {"id": "82449cc4-b6eb-4c96-a77c-75ebb98d3333", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5f259d21-9317-4100-bbcd-b09c6d1e5d94", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW());